import React, { useState, useEffect, useRef } from 'react';
import { buildUrl } from '../utils/apiConfig';
import { useApp } from '../context/AppContext';


const fieldRules = {
  name:  v => v.trim().length > 1,
  branchEmail1: v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()),
  branchPhone: v => v.trim().length >= 7,
  country:     v => v !== '',
  province:    v => v !== '',
  city:        v => v !== '',
  address:     v => v.trim().length > 5,
  academicSession:     v => v.trim().length > 2,
  bankAccountno:   v => v.trim().length > 3,
  iban:        v => v.trim().length > 5,
};

const errorMsgs = {
  name: 'School name is required',
  branchEmail1: 'Enter a valid email address',
  branchPhone: 'Enter a valid phone number',
  country: 'Please select a country',
  province: 'Please select a province',
  city: 'Please select a city',
  address: 'Please enter a complete address',
  session: 'Please enter the academic session',
  accountNo: 'Account number is required',
  iban: 'IBAN is required',
};

function FormInput({ icon, id, type = 'text', placeholder, value, onChange, onBlur, fieldErrors, required }) {
  const status = fieldErrors[id];
  return (
    <div className="input-wrapper">
      {icon && <i className={`fas ${icon} input-icon`}></i>}
      <input
        className={`form-input${icon ? ' has-icon' : ''}${status === 'error' ? ' error-field' : status === 'ok' ? ' success-field' : ''}`}
        id={id} type={type} placeholder={placeholder} value={value}
        onChange={e => onChange(id, e.target.value)}
        onBlur={e => onBlur && onBlur(id, e.target.value)}
      />
    </div>
  );
}

function FieldMsg({ id, fieldErrors }) {
  const status = fieldErrors[id];
  if (!status) return <span className="field-msg" />;
  if (status === 'ok') return <span className="field-msg success"><i className="fas fa-check-circle"></i> Looks good</span>;
  if (status === 'error') return <span className="field-msg error"><i className="fas fa-times-circle"></i> {errorMsgs[id]}</span>;
  return <span className="field-msg" />;
}

export default function SchoolTab({ schoolInfo, setSchoolInfo, onSave, onSaveDraft, markUnsaved, showToast }) {
  const [fieldErrors, setFieldErrors] = useState({});
  const [saving, setSaving] = useState(false);
  const [countryList, setCountryList] = useState([]);
  const [provinceList, setProvinceList] = useState([]);
  const [cityList, setCityList] = useState([]);
  const [logoPreview, setLogoPreview] = useState('');
const [logoFile, setLogoFile] = useState(null);

  const handleChange = (id, val) => {
    setSchoolInfo(prev => ({ ...prev, [id]: val }));
    markUnsaved();
    if (fieldRules[id]) {
      setFieldErrors(prev => ({ ...prev, [id]: fieldRules[id](val) ? 'ok' : 'error' }));
    }
  };

  const handleBlur = (id, val) => {
    if (fieldRules[id]) {
      setFieldErrors(prev => ({ ...prev, [id]: fieldRules[id](val) ? 'ok' : (val ? 'error' : '') }));
    }
  };

  const validateAll = () => {
    const required = ['name','branchEmail1','branchPhone','countryID','provinceID','cityID','address','academicSession'];
    const missing = [];
    const errors = {};
    required.forEach(id => {
      const val = schoolInfo[id] || '';
      const ok = fieldRules[id] ? fieldRules[id](val) : !!val.trim();
      errors[id] = ok ? 'ok' : 'error';
      if (!ok) missing.push(errorMsgs[id] || id);
    });
    setFieldErrors(prev => ({ ...prev, ...errors }));
    return missing;
  };

  const handleSave = async() => {
    const missing = validateAll();
    if (missing.length) { onSave('error', missing); return; }
    setSaving(true);
    const UserID = sessionStorage.getItem('UserID')
    try {
    const res = await fetch(buildUrl('/api/Registration/update-branch'), {
      method: 'PUT',
      headers: {
        'Accept': '*/*',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        id: schoolData.ID,
        name: schoolData.name,
        branchCode: schoolData.branchCode,
        description: schoolData.description,
        address: schoolData.address,
        cityID: schoolData.cityID,
        provinceID: schoolData.provinceID,
        countryID: schoolData.countryID,
        createdAt: schoolData.createdAt,
        createdBy: schoolData.createdBy,
        modifiedAt: new Date().toISOString(),
        modifiedBy: UserID,
        isActive: schoolData.isActive,
        fineFee: schoolData.fineFee,
        fineEnabled: schoolData.fineEnabled,
        branchLogo: schoolData.branchLogo ?? null,
        BranchLogo: schoolData.branchLogo ?? null,
        academicSession: schoolData.academicSession,
        branchOwner: schoolData.branchOwner,
        branchEmail1: schoolData.branchEmail1,
        branchPhone: schoolData.branchPhone,
        bankAccountno: schoolData.bankAccountno,
        accountDesc: schoolData.accountDesc,
        launchSetup: schoolData.launchSetup,
        isManualRegNo: schoolData.isManualRegNo,
        isOperationalSOPs: schoolData.isOperationalSOPs,
        isFeeReceivingHeadWise: schoolData.isFeeReceivingHeadWise,
        isDiscChallan: schoolData.isDiscChallan,
        isTransportFee: schoolData.isTransportFee,
        isPLNeeded: schoolData.isPLNeeded,
      }),
    });

    const data = await res.json();
    console.log("Login Response:", data);
    setSaving(false);
          onSave('success');
getBranchdata()

  } catch (err) {
    showToast('Network error. Please try again.');
    console.error(err);
  }
  };

  const handleDraft = () => {
    setSaving(true);
    setTimeout(() => { setSaving(false); onSaveDraft(); }, 1000);
  };

  useEffect(() => {
  getCountrylist()
