async function getCountrylist() {
      try {
        const res = await fetch(
          buildUrl(`/api/Setting/get-countries`),
          {
            method: 'get',
            headers: {
              'Accept': '*/*',
            },
          }
        );

        const response = await res.json();
            setCountryList(response.data);
      } catch (err) {
        showToast('Network error. Please try again.', 'error');
        console.error(err);
      } finally {
      }
    }

    async function getProvieneList(Country) {
      try {
        const res = await fetch(
          buildUrl(`/api/Setting/get-provinces-by-country/${Country}`),
          {
            method: 'get',
            headers: {
              'Accept': '*/*',
            },
          }
        );

        const response = await res.json();
            setProvinceList(response.data);
      } catch (err) {
        showToast('Network error. Please try again.', 'error');
        console.error(err);
      } finally {
      }
    }

    async function getCityList(province) {
      try {
        const res = await fetch(
          buildUrl(`/api/Setting/get-cities-by-province/${province}`),
          {
            method: 'get',
            headers: {
              'Accept': '*/*',
            },
          }
        );

        const response = await res.json();
            setCityList(response.data);
      } catch (err) {
        showToast('Network error. Please try again.', 'error');
        console.error(err);
      } finally {
      }
    }

